/* OCTAVE offline-capable interface. Dependency-free runtime with live FastAPI endpoints.
   React/TypeScript source is available in frontend/src for full development. */
(()=>{'use strict';
const root=document.getElementById('root');
const icons={scan:'<path d="M4 8V5a1 1 0 0 1 1-1h3m8 0h3a1 1 0 0 1 1 1v3M4 16v3a1 1 0 0 0 1 1h3m8 0h3a1 1 0 0 0 1-1v-3"/><circle cx="12" cy="12" r="3"/>',layers:'<path d="m12 2-9 5 9 5 9-5-9-5Zm-9 10 9 5 9-5M3 17l9 5 9-5"/>',activity:'<path d="M22 12h-4l-3 9L9 3l-3 9H2"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="3"/><path d="M12 0v5M12 19v5M0 12h5M19 12h5"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>',data:'<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14a9 3 0 0 0 18 0V5M3 12a9 3 0 0 0 18 0"/>',plus:'<path d="M12 5v14M5 12h14"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M5 17v4h14v-4"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 17v4h16v-4"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',cube:'<path d="m12 2 9 5-9 5-9-5 9-5ZM3 7v10l9 5 9-5V7M12 12v10"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-10v.5"/>',book:'<path d="M3 5a2 2 0 0 1 2-2h6v18H5a2 2 0 0 0-2 2V5ZM21 5a2 2 0 0 0-2-2h-6v18h6a2 2 0 0 1 2 2V5Z"/>',sliders:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',check:'<path d="m5 12 4 4L19 6"/>',warning:'<path d="m12 2 10 18H2L12 2ZM12 9v4m0 3v.5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',flask:'<path d="M9 3h6m-5 0v7l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M8 16h8"/>'};
const I=(k,n=17)=>`<svg xmlns="http://www.w3.org/2000/svg" width="${n}" height="${n}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]||icons.info}</svg>`;
const names={overview:'Overview',reconstruction:'Reconstruction',vascular:'Vascular analysis',volume:'3D explorer',library:'Dataset library',methods:'Methods & QC'};
const layers={structural:['OCT','Structural'],svc:['SVC','Superficial'],dvc:['DVC','Deep vascular'],avc:['AVC','Avascular'],cc:['CC','Choriocapillaris'],choroid:['CH','Choroid']};
const S={all:[],id:'synthetic-demo',page:'overview',layer:'svc',scan:0,showLayers:true,overlay:false,threshold:52,brightness:100,seed:null,metrics:null,error:null,zoom:false,modal:false,surface:null,visible:{ilm:true,ipl_inl:true,opl_onl:true,rpe:true},yaw:.54,tilt:.65,scale:1};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,k=1)=>v==null?'—':Number(v).toLocaleString('en-US',{maximumFractionDigits:k});
const d=()=>S.all.find(x=>x.id===S.id)||S.all[0];
const route=(tail='')=>`/api/datasets/${encodeURIComponent(d().id)}${tail}`;
const params=()=>`threshold=${S.threshold}${S.seed?`&seed_x=${S.seed.x}&seed_y=${S.seed.y}`:''}`;
const scanSrc=()=>route(`/bscan/${S.scan}?overlay=${S.showLayers}`);
const enfaceSrc=()=>S.overlay&&d().flow_available&&['svc','dvc','cc'].includes(S.layer)?route(`/mask/${S.layer}?${params()}`):route(`/enface/${S.layer}`);
async function req(path,opts){let r=await fetch(path,opts);if(!r.ok){let m=await r.text();try{m=JSON.parse(m).detail||m}catch{}throw Error(typeof m==='string'?m:JSON.stringify(m))}return r.json()}
const nav=[['overview','cube'],['reconstruction','layers'],['vascular','activity'],['volume','scan'],['library','data'],['methods','book']];
function bar(){return `<aside class="sidebar"><div class="brand"><div class="brand-symbol"><div class="brand-pupil"></div></div><div><div class="brand-name">OCTAVE<span class="brand-period">.</span></div><div class="brand-subline">RETINAL RESEARCH STUDIO</div></div></div><div class="nav-block"><span class="overline">WORKSPACE</span><nav>${nav.slice(0,4).map(([k,v])=>`<button class="nav-link ${S.page===k?'active':''}" data-page="${k}">${I(v)}<span>${names[k]}</span>${S.page===k?'<i class="nav-indicator"></i>':''}</button>`).join('')}</nav></div><div class="nav-block secondary"><span class="overline">MANAGE</span><nav>${nav.slice(4).map(([k,v])=>`<button class="nav-link ${S.page===k?'active':''}" data-page="${k}">${I(v)}<span>${names[k]}</span></button>`).join('')}</nav></div><div class="sidebar-bottom"><div class="side-info"><div class="info-icon">${I('flask')}</div><b>Built for discovery.</b><p>Open research tools. Transparent methods. Reproducible analysis.</p><button data-page="methods">Read methodology →</button></div><button class="sidebar-upload" data-action="upload">${I('plus')} New analysis ${I('arrow')}</button><div class="sidebar-footer"><div class="status-dot"></div> SYSTEM ONLINE <span>·</span> v0.1.0</div></div></aside>`}
function top(){return `<header class="topbar"><div class="breadcrumb"><span>Research workspace</span><b>›</b><strong>${names[S.page]}</strong></div><div class="topbar-actions"><span class="research-pill"><span></span> RESEARCH MODE</span><div class="header-sep"></div><button class="topbar-docs" data-page="methods">${I('book')} Documentation</button><div class="avatar">O</div></div></header>`}
function stat(icon,title,val,unit,caption,color){return `<div class="stat-card"><div class="stat-card-top"><span class="stat-label">${title}</span><span class="stat-icon" style="color:${color};background:${color}14">${I(icon,18)}</span></div><div class="stat-value">${val}<span>${unit||''}</span></div><div class="stat-caption"><span class="stat-dash" style="background:${color}"></span>${caption}</div></div>`}
function heading(){const h=S.page==='vascular'?'The vascular landscape':S.page==='reconstruction'?'Reconstruct what matters':'See beneath the surface';const sub=S.page==='vascular'?'Anatomy-guided vessel mapping, quantitative density and transparent FAZ evaluation.':S.page==='reconstruction'?'Transform volumetric B-scans into inspectable, depth-resolved en face views.':'A deeper perspective on retinal structure, microvasculature and the foveal zone.';return `<div class="page-header"><div><div class="page-header-kicker"><span class="kicker-line"></span> ADVANCED OCT & OCTA ANALYSIS <span class="kicker-version">/ RESEARCH STUDIO</span></div><h1>${h}<span class="highlight-dot">.</span></h1><p>${sub}</p></div><div class="page-header-actions"><button class="btn secondary" data-action="export">${I('download')} Export results</button><button class="btn primary" data-action="upload">${I('plus')} New analysis</button></div></div>`}
function study(){const a=d();return `<div class="study-bar"><div class="study-bar-left"><div class="study-icon">${I('scan',20)}</div><div><span>ACTIVE STUDY</span><div class="select-wrapper"><select id="dataset-select" aria-label="Active study">${S.all.map(b=>`<option value="${esc(b.id)}" ${a.id===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div></div></div><div class="study-details"><span>${I('data',14)}${a.shape[0]} B-scans</span><span>${I('scan',14)}${a.shape[2]} × ${a.shape[1]} px</span><span>${I('activity',14)}${a.flow_available?'Paired flow input':'Structural only'}</span></div><div class="study-validity ${a.synthetic||a.preview_sampling?'demo':''}"><span></span>${a.synthetic?'SYNTHETIC DATA':a.preview_sampling?'PREVIEW / SAMPLED':'FULL RESOLUTION'}</div></div>`}
function stats(){const a=d(),m=S.metrics;return `<div class="stats-grid">${stat('activity','VESSEL DENSITY',m?fmt(m.vessel_density_pct,2):'—',m?'%':'',m?'Selected plexus · area fraction':'Flow data required','#11b89e')}${stat('target','FAZ AREA',S.layer==='svc'&&m?.faz_detected?fmt(m.faz_area_mm2??m.faz_area_px,3):'—',S.layer==='svc'&&m?.faz_detected?(m.faz_area_mm2!=null?'mm²':'px²'):'',m?.faz_detected?'Morphological segmentation':'Not detected / SVC only','#eeae68')}${stat('layers','RETINAL THICKNESS',fmt(a.retinal_thickness_um??a.retinal_thickness_px),a.retinal_thickness_um!=null?'µm':'px','Median ILM to RPE · estimated','#8189f3')}${stat('shield','SEGMENTATION QC',a.qc.any_flagged?'Review':'Passed','',a.preview_sampling?'Preview acquisition':'Automated QC · inspect overlays','#16bda2')}</div>`}
function viewer(){const a=d(),vascular=a.flow_available&&['svc','dvc','cc'].includes(S.layer);return `<div class="viewer-shell"><div class="viewer-heading"><div><div class="panel-eyebrow"><span class="live-dot"></span> LIVE WORKSPACE <span class="eyebrow-divider">/</span> MULTIMODAL VIEWER</div><h3>Image reconstruction</h3></div><div class="viewer-heading-right"><span class="sample-label">${a.shape[2]} × ${a.shape[0]} px</span><button class="icon-button" title="Zoom" data-action="zoom">${I('scan')}</button></div></div><div class="layer-selector">${a.layers.map(k=>`<button class="layer-tab ${S.layer===k?'selected':''}" data-layer="${k}"><span>${layers[k][0]}</span>${layers[k][1]}</button>`).join('')}</div><div class="viewer-panes"><div class="image-pane"><div class="pane-top"><div class="pane-name">EN FACE <span>·</span> ${layers[S.layer][0]}</div><div class="pane-status"><span class="dot-cyan"></span> ${S.layer==='structural'?'REFLECTANCE':'FLOW PROJECTION'}</div></div><div class="image-stage enface-stage"><i class="scan-corner top-left"></i><i class="scan-corner top-right"></i><i class="scan-corner bottom-left"></i><i class="scan-corner bottom-right"></i><img id="enface" src="${enfaceSrc()}" alt="${layers[S.layer][1]} en face image" draggable="false" style="filter:brightness(${S.brightness}%);transform:scale(${S.zoom?1.4:1});cursor:${S.layer==='svc'?'crosshair':'default'}"/><div id="lineLayer" style="top:${S.scan/a.shape[0]*100}%"></div><span class="image-axis axis-x">TEMPORAL → NASAL</span><span class="image-axis axis-y">SUPERIOR / INFERIOR</span></div><div class="pane-bottom"><div class="viewer-toolset"><button data-action="original" class="${S.overlay?'':'tool-active'}">${I('eye',13)} Original</button><button data-action="mask" ${vascular?'':'disabled'} class="${S.overlay?'tool-active':''}">${I('target',13)} Vessel overlay</button></div><span class="pane-small">${S.layer==='svc'&&S.overlay?'CLICK TO PLACE FAZ SEED':'EN FACE PROJECTION'}</span></div></div><div class="image-pane"><div class="pane-top"><div class="pane-name">B-SCAN <span>·</span> CROSS-SECTION</div><div class="pane-status">${('00'+(S.scan+1)).slice(-3)} / ${a.shape[0]}</div></div><div class="image-stage bscan-stage"><i class="scan-corner top-left"></i><i class="scan-corner top-right"></i><i class="scan-corner bottom-left"></i><i class="scan-corner bottom-right"></i><img id="bscan" src="${scanSrc()}" alt="OCT B-scan with estimated anatomical layers" style="filter:brightness(${S.brightness}%);transform:scale(${S.zoom?1.4:1})"/><span class="bscan-tag">${S.showLayers?'BOUNDARIES ON':'RAW B-SCAN'}</span></div><div class="pane-bottom"><div class="viewer-toolset"><button data-action="boundaries" class="${S.showLayers?'tool-active':''}">${I('eye',13)} Segmentation</button><button data-action="reset">${I('sliders',13)} Reset view</button></div><span class="pane-small">STRUCTURAL OCT</span></div></div></div><div class="slice-bar"><div class="slice-header"><span>${I('sliders')} B-SCAN POSITION</span><b>Slice ${S.scan+1} <small>/ ${a.shape[0]}</small></b></div><div class="slider-row"><button data-action="prev">‹</button><input id="scan-slider" class="slice-slider" type="range" min="0" max="${a.shape[0]-1}" value="${S.scan}"/><button data-action="next">›</button></div><div class="slice-markers"><span>SUPERIOR</span><span>FOVEAL CENTER</span><span>INFERIOR</span></div></div><div class="viewer-footer"><div class="color-legend"><span><i style="background:#ff7d86"></i>ILM</span><span><i style="background:#ffce78"></i>IPL/INL</span><span><i style="background:#43e5c9"></i>OPL/ONL</span><span><i style="background:#948fff"></i>RPE</span></div><label class="brightness-control"><span>Display</span><input id="brightness" type="range" min="65" max="165" value="${S.brightness}"/></label></div>${S.overlay&&vascular?`<div class="threshold-control"><span>${I('sliders',15)} Vessel percentile</span><input id="threshold" type="range" min="5" max="95" value="${S.threshold}"/><strong>${S.threshold}th</strong><small>Exploratory intensity threshold</small></div>`:''}</div>`}
function inspector(){const a=d(),m=S.metrics,svc=S.layer==='svc',yes=svc&&m?.faz_detected;return `<div class="analysis-inspector"><div class="inspector-title"><span class="overline">ANALYSIS INSIGHTS</span>•••</div><div class="inspector-intro"><div class="inspector-orb">${I('target',25)}</div><h3>Vascular metrics</h3><p>Image-derived quantitative markers from the current segmentation.</p></div><div class="inspector-metric hero-metric"><span>VESSEL AREA DENSITY</span><div>${m?fmt(m.vessel_density_pct,2):'—'} <small>${m?'%':''}</small></div><p>${a.flow_available?'Threshold-derived area fraction':'Requires paired OCTA flow data'}</p></div><div class="inspector-split"><div><span>SKELETON LENGTH</span><b>${m?fmt(m.vessel_length_px_proxy,0):'—'}</b><small>pixel-path proxy</small></div><div><span>FAZ CIRCULARITY</span><b>${yes?fmt(m.faz_circularity,3):'—'}</b><small>${yes?'0–1 range':'SVC / detected only'}</small></div></div><div class="divider-line"></div><div class="inspector-faz"><div class="section-title-sm">${I('target')} FOVEAL AVASCULAR ZONE</div><div class="faz-display"><div><span>FAZ AREA</span><strong>${yes?fmt(m.faz_area_mm2??m.faz_area_px,3):'—'}</strong><small>${yes?(m.faz_area_mm2!=null?'mm²':'px² (uncalibrated)'):'Not detected / unavailable'}</small></div><div class="faz-chip ${yes?'detected':''}">${yes?I('check',12):I('info',12)} ${yes?'ENCLOSED':'UNAVAILABLE'}</div></div><p>${yes?`Closing radius: ${m.closing_radius_px}px. Inspect contour before reporting.`:'No accepted, enclosed FAZ region. Try adjusting vessel threshold or manually placing the seed.'}</p></div><div class="divider-line"></div><div class="quality-title"><span>${I('shield')} QUALITY CONTROL</span><span class="qc-pill ${a.qc.any_flagged?'warning':'good'}">${a.qc.any_flagged?'REVIEW':'CHECKS PASSED'}</span></div><div class="quality-grid"><div><span>Scan mode</span><b>${a.preview_sampling?'Sampled preview':'Full data'}</b></div><div><span>Spatial scales</span><b>${a.calibration.fov_x_mm?'Calibrated':'Not provided'}</b></div><div><span>Source</span><b>${a.synthetic?'Synthetic phantom':'Imported volume'}</b></div></div><div class="inspector-note">${I('info',15)}<p>Research-only measurements. Boundary and threshold errors require expert review. No clinical diagnosis.</p></div></div>`}
function chart(){return `<div class="chart-card"><div class="chart-heading"><div><span class="overline">SPATIAL PROFILE</span><h3>Vessel density across B-scans</h3><p>Area fraction by en face row · exploratory view</p></div><div class="chart-chip"><i class="chart-chip-dot"></i> SELECTED PLEXUS</div></div><div class="chart-body"><canvas id="densityChart" class="chart-visual" title="Click a position to jump to B-scan"></canvas></div><div class="chart-footer"><span>0 <em>SUPERIOR</em></span><span>CLICK PROFILE TO NAVIGATE</span><span><em>INFERIOR</em> ${d().shape[0]}</span></div></div>`}
function warnings(){const a=d();return `<div class="warnings-strip ${a.qc.any_flagged?'alert':''}"><div class="warnings-icon">${I('warning',19)}</div><div><b>${a.preview_sampling?'Preview sampling active':a.synthetic?'Synthetic demonstration active':a.qc.any_flagged?'Segmentation requires review':'Research-grade quality guidance'}</b><p>${esc(a.warnings[0]||'Review results against expert annotations.')}</p></div><button data-page="methods">Read limitations →</button></div>`}
function workspace(){return heading()+study()+stats()+`<div class="workspace-grid">${viewer()}${inspector()}</div><div class="below-grid">${chart()}<div class="quick-actions"><span class="overline">RESEARCH TOOLS</span><h3>Take the analysis further</h3><p>Inspect volumetric anatomy or package reproducible outputs for review.</p><button data-page="volume"><div class="quick-action-icon">${I('scan')}</div><span><b>3D surface explorer</b><small>Explore retinal geometry</small></span>↗</button><button data-action="export"><div class="quick-action-icon amber">${I('download')}</div><span><b>Export research package</b><small>Metrics, provenance & images</small></span>↗</button></div></div>`+warnings()}
function library(){return `<div class="library-page"><div class="section-page-heading"><span class="overline">YOUR RESEARCH LIBRARY</span><h2>Every dataset. One workspace.</h2><p>Analyze imported scans, revisit reconstructions, and move between studies.</p></div><div class="library-toolbar"><div>${I('data')} ${S.all.length} STUDIES AVAILABLE</div><button class="btn primary" data-action="upload">${I('plus')} Import new study</button></div><div class="dataset-grid">${S.all.map(a=>`<button class="dataset-card ${a.id===d().id?'active':''}" data-select="${a.id}"><div class="dataset-thumbnail"><img src="/api/datasets/${a.id}/enface/${a.layers.includes('svc')?'svc':'structural'}" alt="Study preview"/><span>${a.synthetic?'DEMO':'IMPORTED'}</span></div><div class="dataset-content"><div class="dataset-title"><h3>${esc(a.name)}</h3><b>↗</b></div><span class="dataset-meta">${a.shape[0]} B-scans · ${a.flow_available?'OCT + OCTA':'Structural only'}</span><div class="dataset-bottom"><span>${a.preview_sampling?'SAMPLED PREVIEW':'FULL STACK'}</span><span>${a.id===d().id?'✓ ACTIVE':'OPEN STUDY'}</span></div></div></button>`).join('')}<button class="dataset-add" data-action="upload"><div>${I('plus',24)}</div><b>Import another dataset</b><p>Bring your own B-scan stack</p></button></div></div>`}
const cards=[['Volume ingestion','ZIP with numbered PNG/TIFF frames, .npy, .npz, and multi-page TIFF. Axes must be (B-scan, depth, A-scan); paired flow and structural volumes must match.','data'],['Retinal boundaries','Fast intensity-based ILM/RPE estimates; IPL/INL and OPL/ONL are geometric proxies. The original user-provided slow DP boundary tracer is available by configuration.','layers'],['Depth projections','En face reflectance from structural OCT and OCTA projections only from co-registered flow volumes. Includes the provided depth-resolved shadow attenuation method.','activity'],['Vessels and FAZ','Thresholded displayed SVC projection plus morphological closure. FAZ appears only for plausible enclosed region; otherwise return not-detected. No assumption of a 3×3 mm FOV.','target'],['Spatial calibration','FAZ area in mm² requires both lateral dimensions. Retinal thickness in µm requires axial µm/pixel. Without metadata, pixels are the only valid units.','sliders'],['Research validation','This is NOT medically validated, and is not a diagnostic or clinical decision tool. Verify on expert annotations spanning multiple devices and pathologies.','shield']];
function methods(){return `<div class="methods-page"><div class="section-page-heading"><span class="overline">REPRODUCIBLE SCIENCE</span><h2>The method behind the image.</h2><p>Explicit assumptions, inspectable outputs and transparent quality controls.</p></div><div class="method-banner"><div><span>${I('flask')} OPEN RESEARCH ENGINE</span><h3>Every segmentation is a hypothesis to verify.</h3><p>Compare original B-scans against their estimated layers, then trace every downstream metric to its segmentation and scan metadata.</p></div><div class="method-banner-ring">${I('layers',56)}</div></div><div class="methods-grid">${cards.map((a,i)=>`<div class="method-card"><div class="method-num">0${i+1} ${I(a[2],20)}</div><h3>${a[0]}</h3><p>${a[1]}</p></div>`).join('')}</div><div class="references"><h3>Methodological context</h3><p>Inspired by <a href="https://github.com/jaburke166/OCTolyzer" target="_blank" rel="noreferrer">OCTolyzer ↗</a>, <a href="https://github.com/justinengelmann/Choroidalyzer" target="_blank" rel="noreferrer">Choroidalyzer ↗</a>, and supplied OCTA reconstruction / FAZ experiments. Choroidalyzer pretrained weights are not bundled and are not used in the default pipeline.</p></div></div>`}
function volume(){return `<div class="page-header"><div><div class="page-header-kicker">3D RETINAL ANATOMY / INTERACTIVE</div><h1>Explore every contour<span class="highlight-dot">.</span></h1><p>Rotate, zoom and isolate retinal boundaries from the structural volume.</p></div><button class="btn secondary" data-page="reconstruction">${I('layers')} 2D workspace</button></div><div class="volume-layout"><div class="volume-stage"><div class="stage-label">${I('cube')} RETINAL SURFACE EXPLORER <span>INTERACTIVE 3D</span></div><canvas id="threeCanvas"></canvas><div class="stage-caption">${I('sliders',15)} Drag to rotate · Scroll to zoom · Layer visibility at right</div></div><aside class="volume-inspector"><span class="overline">DISPLAY SETTINGS</span><h3>Layer visibility</h3><p>Explore the relative geometry of estimated retinal boundaries. Depth is visually exaggerated. This is not a 3D vascular model.</p><div class="surface-list">${[['ilm','#fb827e','ILM'],['ipl_inl','#ffca80','IPL / INL'],['opl_onl','#37dcbf','OPL / ONL'],['rpe','#8f8cf4','RPE']].map(([k,c,v])=>`<label class="surface-toggle"><span class="surface-dot" style="background:${c}"></span>${v}<input type="checkbox" data-surface="${k}" ${S.visible[k]?'checked':''}/><span class="toggle-track"></span></label>`).join('')}</div><div class="fact-block">${I('info')}<div><b>Research-only geometry</b><span>Surface meshes are estimated and may fail on pathological or unseen imaging protocols.</span></div></div></aside></div>`+warnings()}
function footer(){return `<footer class="page-footer"><div class="footer-lock">${I('flask',14)} OCTAVE RESEARCH STUDIO <span>·</span> NOT FOR CLINICAL DIAGNOSIS</div><div>OCT / OCTA <span>·</span> v0.1.0 <span>·</span> Open research prototype</div></footer>`}
function render(){if(!d()){root.innerHTML='<div id="server-warning"><h2>Analysis server unavailable</h2><p>Run the Python backend to enable datasets.</p><code>cd backend && uvicorn app.main:app --reload</code></div>';return}root.innerHTML=`<div class="app-shell">${bar()}<div class="main-layout">${top()}<main class="main-content">${S.page==='library'?library():S.page==='methods'?methods():S.page==='volume'?volume():workspace()}${footer()}</main></div></div>`;if(S.page==='volume'){ensureSurface()}else if(!['methods','library'].includes(S.page)){drawChart()}}
async function refresh(){S.all=await req('/api/datasets');if(!S.all.some(x=>x.id===S.id))S.id=S.all[0]?.id;const a=d();if(a&&!a.layers.includes(S.layer))S.layer=a.flow_available?'svc':'structural';S.scan=Math.min(S.scan,a?.shape[0]-1||0);await refreshMetrics()}
async function refreshMetrics(){if(!d()?.flow_available||!['svc','dvc','cc'].includes(S.layer)){S.metrics=null;render();return}try{const requested=S.id;const layer=S.layer;const data=await req(`/api/datasets/${requested}/analyze/${layer}?${params()}`);if(requested===S.id&&layer===S.layer)S.metrics=data}catch(e){S.metrics=null;console.warn(e)}render()}
function chartCanvas(){const c=document.getElementById('densityChart');if(!c)return null;const r=c.getBoundingClientRect();const ratio=window.devicePixelRatio||1;c.width=Math.max(1,Math.floor(r.width*ratio));c.height=Math.max(1,Math.floor(r.height*ratio));const g=c.getContext('2d');g.scale(ratio,ratio);return {c,g,w:r.width,h:r.height}}
function drawChart(){const ctx=chartCanvas();if(!ctx)return;const {g,w,h}=ctx;g.clearRect(0,0,w,h);const arr=S.metrics?.row_density_pct;if(!arr?.length){g.font='12px sans-serif';g.fillStyle='#92b1a4';g.textAlign='center';g.fillText('Pair a flow/OCTA volume to see vessel density.',w/2,h/2);return}const lo=8,hi=h-17,top=Math.max(5,Math.ceil(Math.max(...arr)/10)*10);g.strokeStyle='#e6f1ec';g.lineWidth=1;for(let i=0;i<5;i++){const y=lo+i*(hi-lo)/4;g.beginPath();g.moveTo(0,y);g.lineTo(w,y);g.stroke()}let xAt=i=>i/(arr.length-1)*w,yAt=v=>hi-(v/top)*(hi-lo);const grad=g.createLinearGradient(0,lo,0,hi);grad.addColorStop(0,'rgba(52,198,160,.30)');grad.addColorStop(1,'rgba(52,198,160,0)');g.beginPath();g.moveTo(0,hi);arr.forEach((v,i)=>g.lineTo(xAt(i),yAt(v)));g.lineTo(w,hi);g.closePath();g.fillStyle=grad;g.fill();g.beginPath();arr.forEach((v,i)=>i?g.lineTo(xAt(i),yAt(v)):g.moveTo(xAt(i),yAt(v)));g.strokeStyle='#159b83';g.lineWidth=2.2;g.stroke();g.beginPath();g.arc(xAt(S.scan),yAt(arr[S.scan]||0),4,0,Math.PI*2);g.fillStyle='#0a9b82';g.fill();}
let renderId=0;
async function ensureSurface(){if(S.surface){drawSurface();return}const id=S.id;try{S.surface=await req(route('/surface?step=6'));if(id===S.id)drawSurface()}catch(e){console.warn(e)}}
function drawSurface(){const canvas=document.getElementById('threeCanvas');if(!canvas||!S.surface)return;const r=canvas.getBoundingClientRect(),ratio=Math.min(2,window.devicePixelRatio||1),w=Math.max(100,r.width),h=Math.max(100,r.height);canvas.width=w*ratio;canvas.height=h*ratio;const g=canvas.getContext('2d');g.scale(ratio,ratio);g.clearRect(0,0,w,h);g.fillStyle='#0a171b';g.fillRect(0,0,w,h);const ry=S.yaw,rx=S.tilt,scale=S.scale;
const cos=Math.cos,sin=Math.sin,project=(i,j,v,n,m)=>{let x=(j/(m-1)-.5)*9,y=(115-v)*.029,z=(i/(n-1)-.5)*6;let xx=x*cos(ry)-z*sin(ry),zz=x*sin(ry)+z*cos(ry),yy=y*cos(rx)-zz*sin(rx),dep=y*sin(rx)+zz*cos(rx);let f=400*scale/(13+dep);return [w/2+xx*f,h/2+yy*f,dep]};
const spec=[['rpe','#8f8cf4'],['opl_onl','#37dcbf'],['ipl_inl','#ffca80'],['ilm','#fb827e']];for(const [key,color] of spec){if(!S.visible[key])continue;const grid=S.surface.layers[key],n=grid.length,m=grid[0].length;const rgb=color.match(/\w\w/g)?.slice(0,3).map(c=>parseInt(c,16))||[100,200,200];for(let i=0;i<n-1;i++)for(let j=0;j<m-1;j++){let p=[project(i,j,grid[i][j],n,m),project(i+1,j,grid[i+1][j],n,m),project(i+1,j+1,grid[i+1][j+1],n,m),project(i,j+1,grid[i][j+1],n,m)];g.beginPath();g.moveTo(p[0][0],p[0][1]);for(let a=1;a<4;a++)g.lineTo(p[a][0],p[a][1]);g.closePath();g.fillStyle=`rgba(${rgb[0]},${rgb[1]},${rgb[2]},.21)`;g.strokeStyle=`rgba(${rgb[0]},${rgb[1]},${rgb[2]},.24)`;g.lineWidth=.45;g.fill();g.stroke()}}
}
function select(id){S.id=id;S.layer=d().flow_available?'svc':'structural';S.scan=Math.floor(d().shape[0]/2);S.seed=null;S.overlay=false;S.surface=null;S.page='overview';refreshMetrics()}
function modal(){S.modal=true;const block=document.createElement('div');block.className='modal-backdrop';block.id='upload-backdrop';block.innerHTML=`<div class="upload-modal" role="dialog" aria-modal="true" aria-label="Import OCT volume"><div class="modal-heading"><div><span class="overline">NEW WORKSPACE SESSION</span><h2>Import your OCT volume</h2><p>Bring your own data and reconstruct depth-resolved retina maps.</p></div><button id="modal-close" class="icon-button">✕</button></div><form id="upload-form"><label><span class="field-label">STUDY NAME</span><input name="name" value="Untitled OCT study" maxlength="120" required/></label><div class="file-grid" style="margin:16px 0"><label class="dropzone"><div class="drop-icon">${I('upload',20)}</div><b>Structural OCT</b><small>Required · ZIP / NPY / NPZ / TIFF</small><input type="file" name="structural" accept=".zip,.npy,.npz,.tif,.tiff" required style="max-width:95%;font-size:10px"/></label><label class="dropzone"><div class="drop-icon">${I('activity',20)}</div><b>Paired flow / OCTA</b><small>Optional · matched registered stack</small><input type="file" name="flow" accept=".zip,.npy,.npz,.tif,.tiff" style="max-width:95%;font-size:10px"/></label></div><div class="modal-section-head"><b>Spatial calibration</b><span>Optional; no scale is assumed</span></div><div class="row3" style="margin:11px 0 18px"><label><span class="field-label">FOV WIDTH (mm)</span><input name="fov_x_mm" type="number" min="0.01" max="60" step="any" placeholder="e.g. 3"/></label><label><span class="field-label">FOV HEIGHT (mm)</span><input name="fov_y_mm" type="number" min="0.01" max="60" step="any" placeholder="e.g. 3"/></label><label><span class="field-label">AXIAL (µm/px)</span><input name="axial_um_per_px" type="number" min="0.01" max="50" step="any" placeholder="Optional"/></label></div><label><span class="field-label">PROCESSING RESOLUTION</span><select name="max_slices"><option value="128">Preview · up to 128 B-scans</option><option value="256">High detail · up to 256 B-scans</option><option value="0">Full resolution · all B-scans</option></select></label><div class="upload-warning" style="margin-top:16px">${I('info')} Use de-identified research data. Uploads stay on this local server. Preview-sampled outputs are not for quantitative studies.</div><p id="modal-error" style="color:#b3584f;font-size:11px"></p><div class="modal-actions"><button type="button" class="btn secondary" id="cancel-modal">Cancel</button><button type="submit" class="btn primary" id="submit-modal">${I('flask')} Start reconstruction ${I('arrow')}</button></div></form><div id="job-status" style="display:none;text-align:center;padding:60px 15px"><h2>Processing your volume</h2><p id="job-stage">Reading input files…</p><div class="progress-track"><div id="job-fill" style="height:100%;width:0;background:#26b997"></div></div><p id="job-percent">0%</p></div></div>`;document.body.appendChild(block);block.addEventListener('click',e=>{if(e.target===block||e.target.id==='modal-close'||e.target.id==='cancel-modal'){S.modal=false;block.remove()}});block.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const form=e.target;const fd=new FormData(form);for(const k of ['fov_x_mm','fov_y_mm','axial_um_per_px'])if(!fd.get(k))fd.delete(k);if(!fd.get('flow')?.name)fd.delete('flow');const x=fd.has('fov_x_mm'),y=fd.has('fov_y_mm');if(x!==y){document.getElementById('modal-error').textContent='Provide both lateral scan dimensions, or neither.';return}const btn=document.getElementById('submit-modal');btn.disabled=true;btn.textContent='Uploading…';try{const job=await req('/api/datasets',{method:'POST',body:fd});form.style.display='none';document.getElementById('job-status').style.display='block';while(true){await new Promise(r=>setTimeout(r,1100));const q=await req('/api/jobs/'+job.id);document.getElementById('job-stage').textContent=q.error||q.stage;document.getElementById('job-percent').textContent=Math.round(q.progress*100)+'%';document.getElementById('job-fill').style.width=(q.progress*100)+'%';if(q.status==='failed')throw Error(q.error||'Analysis failed');if(q.status==='complete'){S.modal=false;block.remove();S.all=await req('/api/datasets');select(q.dataset_id);break}}}catch(e){document.getElementById('job-status').style.display='none';form.style.display='block';btn.disabled=false;btn.textContent='Start reconstruction';document.getElementById('modal-error').textContent=e.message}})}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.page){S.page=b.dataset.page;render();return}if(b?.dataset.select){select(b.dataset.select);return}if(b?.dataset.layer){S.layer=b.dataset.layer;S.overlay=false;S.seed=null;refreshMetrics();return}const act=b?.dataset.action;if(act==='upload'){modal();return}if(act==='export'){window.location.href=route('/export?'+params());return}if(act==='prev'){S.scan=Math.max(0,S.scan-1);render();return}if(act==='next'){S.scan=Math.min(d().shape[0]-1,S.scan+1);render();return}if(act==='boundaries'){S.showLayers=!S.showLayers;render();return}if(act==='mask'){S.overlay=true;render();return}if(act==='original'){S.overlay=false;render();return}if(act==='zoom'){S.zoom=!S.zoom;render();return}if(act==='reset'){S.zoom=false;S.brightness=100;render();return}if(e.target.id==='enface'&&S.layer==='svc'&&d().flow_available){const a=d(),r=e.target.getBoundingClientRect();S.seed={x:Math.max(0,Math.min(a.shape[2]-1,Math.round((e.clientX-r.left)/r.width*a.shape[2]))),y:Math.max(0,Math.min(a.shape[0]-1,Math.round((e.clientY-r.top)/r.height*a.shape[0])))};S.overlay=true;refreshMetrics();return}if(e.target.id==='densityChart'&&S.metrics){const r=e.target.getBoundingClientRect();S.scan=Math.max(0,Math.min(d().shape[0]-1,Math.round((e.clientX-r.left)/r.width*(d().shape[0]-1))));render()}});
root.addEventListener('input',e=>{const t=e.target;if(t.id==='scan-slider'){S.scan=+t.value;const img=document.getElementById('bscan');if(img)img.src=scanSrc();const line=document.getElementById('lineLayer');if(line)line.style.top=`${100*S.scan/d().shape[0]}%`;const text=document.querySelector('.slice-header b');if(text)text.innerHTML=`Slice ${S.scan+1} <small>/ ${d().shape[0]}</small>`;drawChart()}if(t.id==='brightness'){S.brightness=+t.value;root.querySelectorAll('.image-stage img').forEach(x=>x.style.filter=`brightness(${S.brightness}%)`)}if(t.id==='threshold'){S.threshold=+t.value;const tx=document.querySelector('.threshold-control strong');if(tx)tx.textContent=S.threshold+'th';clearTimeout(renderId);renderId=setTimeout(()=>refreshMetrics(),280)}});
root.addEventListener('change',e=>{if(e.target.id==='dataset-select')select(e.target.value);if(e.target.dataset.surface){S.visible[e.target.dataset.surface]=e.target.checked;drawSurface()}});
let drag=null;root.addEventListener('pointerdown',e=>{if(e.target.id==='threeCanvas'){drag={x:e.clientX,y:e.clientY,yaw:S.yaw,tilt:S.tilt};e.target.setPointerCapture(e.pointerId)}});root.addEventListener('pointermove',e=>{if(!drag)return;S.yaw=drag.yaw+(e.clientX-drag.x)*.007;S.tilt=Math.max(-1.35,Math.min(1.35,drag.tilt+(e.clientY-drag.y)*.007));drawSurface()});root.addEventListener('pointerup',()=>drag=null);root.addEventListener('wheel',e=>{if(e.target.id==='threeCanvas'){e.preventDefault();S.scale=Math.max(.5,Math.min(3,S.scale*(e.deltaY>0?.92:1.09)));drawSurface()}},{passive:false});window.addEventListener('resize',()=>{if(S.page==='volume')drawSurface();else drawChart()});
refresh().catch(err=>{root.innerHTML=`<div id="server-warning"><h2>Analysis server unavailable</h2><p>${esc(err.message)}</p><code>cd backend && uvicorn app.main:app --reload</code></div>`});
})();
